(() => {
  async function open(){
    const dialog=document.createElement('dialog');dialog.className='chat-small-dialog';dialog.setAttribute('aria-label','工作台设置');dialog.innerHTML='<form><h2>工作台设置</h2><label>执行前如何确认<select name="approvalMode"><option value="ask">每次问我</option><option value="auto_sandbox">帮我批准受限沙盒测试</option></select></label><p>“帮我批准”只适用于新任务中的测试：在无网络、项目文件只读的隔离容器内执行。提交、合并、回滚仍由你确认。当前运行的任务保持原设置。</p><p>需要本机安装并启动 Docker，缺少沙盒时仍会停下来提示。</p><button class="text-link" type="button" id="prefModels">管理多家模型与角色分工 →</button><p id="prefError" role="alert"></p><div class="button-row"><button type="button" class="outline-button" id="prefClose">取消</button><button type="submit" class="primary-button">保存设置</button></div></form>';document.body.append(dialog);dialog.showModal();dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.querySelector('#prefClose').onclick=()=>dialog.close();dialog.querySelector('#prefModels').onclick=()=>{dialog.close();window.RuntimeUI.openSettings();};
    try{const response=await fetch('/api/status');if(!response.ok)throw new Error('无法读取设置');const data=await response.json();dialog.querySelector('select').value=data.config.approvalMode||'ask';}catch(e){dialog.querySelector('#prefError').textContent=e.message;dialog.querySelector('[type=submit]').disabled=true;}
    dialog.querySelector('form').onsubmit=async event=>{event.preventDefault();const button=dialog.querySelector('[type=submit]');button.disabled=true;try{const response=await fetch('/api/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({approvalMode:dialog.querySelector('select').value})});const data=await response.json();if(!response.ok)throw new Error(data.message||'保存失败');dialog.close();window.Gongming.toast('审批方式已保存，对新任务生效');}catch(e){dialog.querySelector('#prefError').textContent=e.message;}finally{button.disabled=false;}};
  }
  document.addEventListener('click',e=>{if(e.target.closest('button[data-action="settings"]')){e.preventDefault();e.stopImmediatePropagation();if(window.NavigationUI)window.Gongming.openView('settings');else open();}},true);
  window.PreferencesUI={open};
})();
